   var position=cell(x,y,z);
   if(!NativeBuilderFormation.loaded(level,position))continue;
   if(drive()==null){
    if(level.hasNeighborSignal(position))signal=15;
   }else signal=Math.max(signal,NativeLoadedRedstonePower.level(level,position));
